const int echoPin = 3;

void setup() {
  // Initialize serial communication at 9600 baud
  Serial.begin(9600);

  // Set TRIG pin as output to send the trigger pulse
  pinMode(trigPin, OUTPUT);

  // Set ECHO pin as input to read the echo pulse
  pinMode(echoPin, INPUT);
}

